/** What a backup leaves out, and when the weekly one is due. Pure, tested. */

/** Tables of the OAuth server for Claude: tokens, regenerated by reconnecting. */
export const BACKUP_SKIPPED_MODELS = ["OAuthClient", "OAuthCode", "OAuthToken"];

/** Settings holding credentials: never written to a backup. */
export function isSecretSetting(key: string): boolean {
  return (
    /^(telegram\.(botToken|webhookSecret)|cron\.secret|youtube\.apiKey|google\.drive\.)/.test(
      key,
    ) || key.startsWith("kdp.autosync.")
  );
}

/** Day of the week (0 = Sunday) of a "YYYY-MM-DD" day. */
const weekday = (day: string) => new Date(`${day}T00:00:00Z`).getUTCDay();

const daysBetween = (a: string, b: string) =>
  Math.round((Date.parse(`${b}T00:00:00Z`) - Date.parse(`${a}T00:00:00Z`)) / 86_400_000);

/**
 * The weekly backup runs on Sunday from `hour`, once; a week without one
 * (the Sunday missed) catches up on the next run.
 */
export function backupDue(today: string, hourNow: number, lastDay: string | null, hour = 3) {
  if (lastDay === today) return false;
  if (lastDay && daysBetween(lastDay, today) > 7) return true;
  if (!lastDay) return hourNow >= hour;
  return weekday(today) === 0 && hourNow >= hour;
}

/** Backups kept in the Drive folder; older ones are deleted. */
export const BACKUPS_KEPT = 12;
